<template>
  <div class="container">
    <div class="user-detail-content" v-if="userDetail">
      <!-- Profile Header -->
      <ProfileHeader
        :user="userDetail"
        @edit="handleEdit"
        @delete="handleDeleteUser"
        class="q-mt-md"
      />

      <!-- Information Cards Row -->
      <div class="row q-col-gutter-md q-mt-md">
        <div class="col-12 col-md-6">
          <AccountInfoCard :user="userDetail" />
        </div>
        <div class="col-12 col-md-6">
          <AccessMembershipCard :user="userDetail" />
        </div>
      </div>

      <!-- Activity Card -->
      <div class="q-mt-md q-pb-md">
        <ActivityCard :user="userDetail" />
      </div>
    </div>
  </div>

  <Loader />

  <UserFormDialog
    v-model="userDialog"
    :user="userDetail"
    @saved="onUserSaved"
  />

  <!-- Delete Confirmation Dialog -->
  <q-dialog v-model="confirmDelete" persistent>
    <q-card style="min-width: 500px; max-width: 600px; border-radius: 12px">
      <!-- Warning Icon Header -->
      <q-card-section class="row justify-center q-pt-lg q-pb-md">
        <div class="warning-icon-container">
          <q-icon name="warning" size="80px" color="negative" />
        </div>
      </q-card-section>

      <!-- Title -->
      <q-card-section class="q-pt-none q-pb-sm text-center">
        <div class="text-h5 text-weight-medium">
          Delete User '{{ userDetail?.first_name }}
          {{ userDetail?.last_name }}'?
        </div>
      </q-card-section>

      <!-- Description -->
      <q-card-section class="q-pt-none q-pb-lg text-center">
        <div class="text-body1 text-grey-8" style="line-height: 1.6">
          This will permanently remove the user and all assigned permissions.
          This action cannot be undone.
        </div>
      </q-card-section>

      <!-- Actions -->
      <q-card-actions align="center" class="q-px-lg q-pb-lg q-gutter-sm">
        <f-btn
          :label="$t('cancel')"
          appearance="cancel"
          v-close-popup
          style="min-width: 140px"
        />
        <f-btn
          label="Delete User"
          appearance="negative"
          v-close-popup
          @click="deleteUserConfirmed()"
          style="min-width: 140px"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useUserStore } from 'src/store/main';
import Loader from 'components/Loader.vue';
import helperMixin from 'src/mixins/helperMixin';
import { ApiExceptions } from 'src/exceptions';
import { dynamicObj } from 'pages/assets';
import ProfileHeader from 'src/components/Settings/Users/ProfileHeader.vue';
import AccountInfoCard from 'src/components/Settings/Users/AccountInfoCard.vue';
import AccessMembershipCard from 'src/components/Settings/Users/AccessMembershipCard.vue';
import ActivityCard from 'src/components/Settings/Users/ActivityCard.vue';
import UserFormDialog from 'src/components/Settings/Users/UserFormDialog.vue';
import { userApiService } from 'src/services';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  data() {
    return {
      userDialog: ref(false),
    };
  },
  components: {
    Loader,
    ProfileHeader,
    AccountInfoCard,
    AccessMembershipCard,
    ActivityCard,
    UserFormDialog,
  },
  mounted() {
    this.init();
  },
  unmounted() {
    this.resetUserDetailStore();
  },
  methods: {
    async init() {
      this.showLoading();
      this.resetUserDetailStore();

      const id = this.$route.params.id as string;
      try {
        await this.getUserDetailWithGroupAndSubOrgByUserId(id);
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    handleEdit() {
      this.userDialog = true;
    },

    async onUserSaved() {
      const id = this.$route.params.id as string;
      await this.getUserDetailWithGroupAndSubOrgByUserId(id);
    },

    handleManagePermissions() {
      const userId = this.$route.params.id;
      this.$router.push(`/settings/user/permissions/${userId}`);
    },

    handleDeleteUser() {
      this.confirmDelete = true;
    },

    async deleteUserConfirmed() {
      try {
        this.showLoading();
        const userId = this.$route.params.id as string;
        const response = await userApiService.deleteUser(userId);

        if (response?.success === false) {
          throw response;
        }

        notify.success(this.$t('delete_user_success'));
        this.$router.push('/settings/users');
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.confirmDelete = false;
        this.hideLoading();
      }
    },
  },
  setup() {
    const user_store = useUserStore();
    const { getUserDetailWithGroupAndSubOrgByUserId, resetUserDetailStore } =
      user_store;
    const { userDetail } = storeToRefs(user_store);

    return {
      confirmDelete: ref(false),
      getUserDetailWithGroupAndSubOrgByUserId,
      resetUserDetailStore,
      userDetail,
    };
  },
});
</script>

<style scoped lang="scss">
.user-detail-content {
  height: calc(100vh - 120px);
  overflow-y: auto;
}
</style>
