<template>
  <q-card class="activity-card back-white">
    <q-card-section>
      <div class="text-subtitle1 text-weight-medium q-mb-md card-title">
        <q-icon name="history" class="q-mr-sm" />
        {{ $t('recent_activity') }}
      </div>

      <!-- Last Login Info -->
      <div class="activity-item">
        <div class="activity-icon">
          <q-icon name="login" color="primary" size="24px" />
        </div>
        <div class="activity-content">
          <div class="activity-label text-weight-medium">
            {{ $t('last_login') }}
          </div>
          <div class="activity-value text-grey-7">
            {{ formattedLastLogin }}
          </div>
        </div>
      </div>

      <!-- Last Edited Info -->
      <div class="activity-item" v-if="user.last_edited_by">
        <div class="activity-icon">
          <q-icon name="edit" color="warning" size="24px" />
        </div>
        <div class="activity-content">
          <div class="activity-label text-weight-medium">
            {{ $t('last_edited_by') }}
          </div>
          <div class="activity-value text-grey-7">
            {{ user.last_edited_by }} • {{ formattedLastEditedDate }}
          </div>
        </div>
      </div>

      <!-- Login History List -->
      <div class="q-mt-md">
        <div class="text-subtitle2 text-weight-medium q-mb-sm">
          {{ $t('login_history') }}
        </div>
        <ActivityList
          :login-history="loginHistory"
          :loading="loadingHistory"
          :error="historyError"
          :show-load-more="false"
        />
      </div>
    </q-card-section>
  </q-card>
</template>

<script setup lang="ts">
import { computed, ref, onMounted, watch } from 'vue';
import ActivityList from './ActivityList.vue';
import { userApiService } from '@/services';
import { useTranslate } from '@tolgee/vue';
import { useFormattedTimeAgo } from 'src/boot/timeago';

export interface User {
  id?: string | number;
  last_logged_in?: string;
  last_edited_by?: string;
  last_edited_on?: string;
}

const props = withDefaults(
  defineProps<{
    user: User;
    showLoginFrequency?: boolean;
  }>(),
  {
    showLoginFrequency: false,
  },
);

const { t } = useTranslate();

const loginHistory = ref<any[]>([]);
const loadingHistory = ref(false);
const historyError = ref<string | undefined>();

const fetchLoginHistory = async () => {
  if (!props.user.id) return;

  loadingHistory.value = true;
  historyError.value = undefined;

  try {
    const response = await userApiService.getUserLoginHistoryById(
      String(props.user.id),
      10, // limit
      true, // includeFailures
    );
    loginHistory.value = response.login_history || [];
  } catch (error) {
    console.error('[ACTIVITY CARD] Failed to fetch login history:', error);
    historyError.value = t.value('login_history_error');
  } finally {
    loadingHistory.value = false;
  }
};

onMounted(() => {
  fetchLoginHistory();
});

// Re-fetch when user changes
watch(
  () => props.user.id,
  (newId) => {
    if (newId) {
      fetchLoginHistory();
    }
  },
);

const formattedLastLogin = computed(() => {
  // Priority 1: Use most recent login from login history (accurate, from auth service)
  if (loginHistory.value?.length > 0) {
    const mostRecent = loginHistory.value[0];
    if (mostRecent.login_timestamp) {
      return useFormattedTimeAgo(mostRecent.login_timestamp);
    }
  }
  // Priority 2: Fallback to cached field
  if (props.user.last_logged_in) {
    return useFormattedTimeAgo(props.user.last_logged_in);
  }
  return t.value('never');
});

const formattedLastEditedDate = computed(() => {
  if (!props.user.last_edited_on) return '';
  return useFormattedTimeAgo(props.user.last_edited_on);
});
</script>

