<template>
  <q-card class="account-info-card back-white">
    <q-card-section>
      <div class="text-subtitle1 text-weight-medium q-mb-md card-title">
        <q-icon name="info" class="q-mr-sm" />
        {{ $t('account_information') }}
      </div>

      <div class="info-row">
        <span class="label">{{ $t('log_created_on') }}</span>
        <span class="value">{{ formattedCreatedDate }}</span>
      </div>

      <div class="info-row">
        <span class="label">{{ $t('company') }}</span>
        <span class="value">{{ user.company_name || '-' }}</span>
      </div>

      <div class="info-row" v-if="user.role">
        <span class="label">{{ $t('role') }}</span>
        <span class="value">{{ user.role }}</span>
      </div>

      <div class="info-row">
        <span class="label">{{ $t('admin_user') }}</span>
        <div class="value-with-icon">
          <q-icon
            :name="user.is_organisation_admin ? 'check_circle' : 'cancel'"
            :color="user.is_organisation_admin ? 'positive' : 'negative'"
            size="20px"
          />
          <span class="q-ml-xs">
            {{ user.is_organisation_admin ? $t('yes') : $t('no') }}
          </span>
        </div>
      </div>

      <div class="info-row">
        <span class="label">{{ $t('user_system_admin') }}</span>
        <div class="value-with-icon">
          <q-icon
            :name="user.is_system_user ? 'check_circle' : 'cancel'"
            :color="user.is_system_user ? 'positive' : 'negative'"
            size="20px"
          />
          <span class="q-ml-xs">
            {{ user.is_system_user ? $t('yes') : $t('no') }}
          </span>
        </div>
      </div>
    </q-card-section>
  </q-card>
</template>

<script setup lang="ts">
import { computed } from 'vue';
import { format, parseISO } from 'date-fns';

export interface User {
  created_on?: string;
  company_name?: string;
  role?: string;
  is_organisation_admin?: boolean;
  is_system_user?: boolean;
}

const props = defineProps<{
  user: User;
}>();

const formattedCreatedDate = computed(() => {
  if (!props.user.created_on) return '-';

  try {
    const date = parseISO(props.user.created_on);
    return format(date, 'MMM dd, yyyy');
  } catch (error) {
    return props.user.created_on;
  }
});
</script>

