<template>
  <q-card class="profile-header back-white q-pa-lg">
    <div class="row items-center">
      <!-- Avatar Section -->
      <div class="col-auto q-mr-lg">
        <q-avatar
          size="80px"
          color="primary"
          text-color="white"
          class="text-h4"
        >
          {{ userInitials }}
        </q-avatar>
      </div>

      <!-- User Info -->
      <div class="col">
        <div class="row items-center q-mb-xs">
          <h5 class="text-h5 text-bold q-ma-none q-mr-sm user-info-text">
            {{ user.first_name }} {{ user.last_name }}
          </h5>
          <q-badge :color="statusColor" :label="statusLabel" rounded />
        </div>

        <div class="text-body2 user-info-text q-mb-xs">
          <q-icon name="email" size="16px" class="q-mr-xs" />
          {{ user.email }}
        </div>

        <div class="text-caption user-last-login">
          <q-icon name="schedule" size="14px" class="q-mr-xs" />
          {{ $t('last_login') }}: {{ formattedLastLogin }}
        </div>
      </div>

      <!-- Action Buttons -->
      <div class="col-auto action-buttons">
        <q-btn
          flat
          color="primary"
          icon="edit"
          :label="$t('edit')"
          @click="$emit('edit')"
          class="q-mr-sm"
        />
        <q-btn
          flat
          color="negative"
          icon="delete"
          :label="$t('delete_user')"
          @click="$emit('delete')"
        />
      </div>
    </div>
  </q-card>
</template>

<script setup lang="ts">
import { computed, ref, onMounted, watch } from 'vue';
import { useTranslate } from '@tolgee/vue';
import { useFormattedTimeAgo } from 'src/boot/timeago';
import { userApiService } from '@/services';

export interface User {
  id?: string | number;
  first_name?: string;
  last_name?: string;
  email?: string;
  last_logged_in?: string;
  is_active?: boolean;
}

const props = defineProps<{
  user: User;
}>();

defineEmits(['edit', 'delete']);

const { t } = useTranslate();

const loginHistory = ref<any[]>([]);

const fetchLoginHistory = async () => {
  if (!props.user.id) return;

  try {
    const response = await userApiService.getUserLoginHistoryById(
      String(props.user.id),
      1, // Only need the most recent login
      false, // Don't need failures for display
    );
    loginHistory.value = response.login_history || [];
  } catch (error) {
    console.error('[PROFILE HEADER] Failed to fetch login history:', error);
  }
};

onMounted(() => {
  fetchLoginHistory();
});

// Re-fetch when user changes
watch(
  () => props.user.id,
  (newId) => {
    if (newId) {
      fetchLoginHistory();
    }
  },
);

const userInitials = computed(() => {
  const first = props.user.first_name?.[0] || '';
  const last = props.user.last_name?.[0] || '';
  return (first + last).toUpperCase();
});

const statusColor = computed(() => {
  return props.user.is_active !== false ? 'positive' : 'negative';
});

const statusLabel = computed(() => {
  return props.user.is_active !== false
    ? t.value('active')
    : t.value('inactive');
});

const formattedLastLogin = computed(() => {
  // Priority 1: Use most recent login from login history (accurate, from auth service)
  if (loginHistory.value?.length > 0) {
    const mostRecent = loginHistory.value[0];
    if (mostRecent.login_timestamp) {
      return useFormattedTimeAgo(mostRecent.login_timestamp);
    }
  }
  // Priority 2: Fallback to cached field
  if (props.user.last_logged_in) {
    return useFormattedTimeAgo(props.user.last_logged_in);
  }
  return t.value('never');
});
</script>

