<template>
  <div class="activity-list">
    <q-spinner v-if="loading" color="primary" size="40px" class="q-my-md" />

    <div v-else-if="error" class="error-state q-pa-md">
      <q-icon name="error_outline" color="negative" size="32px" />
      <div class="text-body2 text-negative q-mt-sm">{{ error }}</div>
    </div>

    <div
      v-else-if="loginHistory.length === 0"
      class="empty-state q-pa-md text-center"
    >
      <q-icon name="history" color="grey-5" size="48px" />
      <div class="text-body2 text-grey-7 q-mt-sm">
        {{ $t('no_login_history') }}
      </div>
    </div>

    <div v-else class="activity-entries">
      <div
        v-for="(entry, index) in loginHistory"
        :key="entry.id || index"
        class="activity-entry"
      >
        <div class="activity-icon-wrapper">
          <q-icon
            :name="getLoginMethodIcon(entry.login_method)"
            :color="entry.success ? 'primary' : 'negative'"
            size="20px"
          />
        </div>

        <div class="activity-details">
          <div class="activity-header">
            <span class="activity-method">{{
              formatLoginMethod(entry.login_method)
            }}</span>
            <span v-if="!entry.success" class="failed-badge">
              <q-chip dense size="sm" color="negative" text-color="white">
                {{ $t('failed') }}
              </q-chip>
            </span>
          </div>

          <div class="activity-meta text-grey-7">
            <span class="activity-time">{{
              formatTimestamp(entry.login_timestamp)
            }}</span>
            <span v-if="entry.ip_address" class="activity-ip">
              <q-icon name="location_on" size="14px" class="q-mr-xs" />
              {{ entry.ip_address }}
              <span v-if="entry.location_city || entry.location_country" class="activity-location q-ml-xs">
                ({{ [entry.location_city, entry.location_country].filter(Boolean).join(', ') }})
              </span>
            </span>
          </div>

          <div
            v-if="entry.failure_reason"
            class="failure-reason text-negative text-caption"
          >
            {{ entry.failure_reason }}
          </div>
        </div>
      </div>
    </div>

    <div
      v-if="loginHistory.length > 0 && showLoadMore"
      class="load-more-section q-mt-md text-center"
    >
      <q-btn
        flat
        color="primary"
        :label="$t('load_more')"
        icon="expand_more"
        @click="$emit('load-more')"
      />
    </div>
  </div>
</template>

<script setup lang="ts">
import { computed } from 'vue';
import { useTranslate } from '@tolgee/vue';
import { format, parseISO } from 'date-fns';
import { useFormattedTimeAgo } from 'src/boot/timeago';

interface LoginHistoryEntry {
  id: string;
  user_id: number;
  org_id: string;
  login_timestamp: string;
  login_method: string;
  ip_address?: string;
  location_city?: string;
  location_country?: string;
  location_country_code?: string;
  user_agent?: string;
  session_id?: string;
  success: boolean;
  failure_reason?: string;
}

interface Props {
  loginHistory: LoginHistoryEntry[];
  loading?: boolean;
  error?: string;
  showLoadMore?: boolean;
}

const props = withDefaults(defineProps<Props>(), {
  loginHistory: () => [],
  loading: false,
  error: undefined,
  showLoadMore: false,
});

defineEmits(['load-more']);

const { t } = useTranslate();

const getLoginMethodIcon = (method: string): string => {
  const icons: Record<string, string> = {
    password: 'vpn_key',
    google: 'mdi:google',
    linkedin: 'mdi:linkedin',
    microsoft: 'mdi:microsoft',
    saml: 'security',
    api_key: 'key',
    token: 'token',
  };
  return icons[method] || 'login';
};

const formatLoginMethod = (method: string): string => {
  const methods: Record<string, string> = {
    password: t.value('login_method_password'),
    google: 'Google',
    linkedin: 'LinkedIn',
    microsoft: 'Microsoft',
    saml: 'SAML SSO',
    api_key: 'API Key',
    token: 'OAuth Token',
    refresh_token: 'OAuth Refresh Token',
  };
  return methods[method] || method;
};

const formatTimestamp = (timestamp: string): string => {
  try {
    const date = parseISO(timestamp);
    const relative = useFormattedTimeAgo(timestamp);
    const absolute = format(date, 'MMM dd, yyyy HH:mm');
    return `${relative} (${absolute})`;
  } catch (error) {
    console.error('[ACTIVITY LIST] Error formatting timestamp:', error);
    return timestamp;
  }
};
</script>

